func (r webhookSourceRow) Scan(dest ...any) error {
	values := []any{
		r.src.ID,
		r.src.WorkspaceID,
		r.src.RepoURL,
		r.src.RepoOwner,
		r.src.RepoName,
		r.src.DefaultBranch,
		r.src.CreatedAt,
		r.src.UpdatedAt,
	}
	if len(dest) != len(values) {
		return fmt.Errorf("expected %d scan destinations, got %d", len(values), len(dest))
	}
	for i := range dest {
		switch d := dest[i].(type) {
		case *pgtype.UUID:
			v, ok := values[i].(pgtype.UUID)
			if !ok {
				return fmt.Errorf("scan[%d]: expected pgtype.UUID, got %T", i, values[i])
			}
			*d = v
		case *string:
			v, ok := values[i].(string)
			if !ok {
				return fmt.Errorf("scan[%d]: expected string, got %T", i, values[i])
			}
			*d = v
		case **string:
			v, ok := values[i].(*string)
			if !ok {
				return fmt.Errorf("scan[%d]: expected *string, got %T", i, values[i])
			}
			*d = v
		case *pgtype.Timestamptz:
			v, ok := values[i].(pgtype.Timestamptz)
			if !ok {
				return fmt.Errorf("scan[%d]: expected pgtype.Timestamptz, got %T", i, values[i])
			}
			*d = v
		default:
			return fmt.Errorf("unsupported scan destination %T", dest[i])
		}
	}
	return nil
}

