func (f *fakeSyncRunDB) Exec(context.Context, string, ...interface{}) (pgconn.CommandTag, error) {
	return pgconn.CommandTag{}, errors.New("not implemented")
}

func (f *fakeSyncRunDB) Query(context.Context, string, ...interface{}) (pgx.Rows, error) {
	return nil, errors.New("not implemented")
}

func (f *fakeSyncRunDB) QueryRow(_ context.Context, query string, args ...interface{}) pgx.Row {
	switch {
	case strings.Contains(query, "FROM workspaces"):
		return workspaceRow{workspaceID: f.workspaceID}
	case strings.Contains(query, "FROM workspace_features"):
		return errorRow{err: pgx.ErrNoRows}
	case strings.Contains(query, "INSERT INTO workspace_sync_runs"):
		f.insertSyncRunCalls++
		if len(args) > 5 {
			if mode, ok := args[5].(string); ok {
				f.lastMode = mode
			}
		}
		return syncRunRow{
			id:          f.runID,
			workspaceID: f.workspaceID,
			status:      "running",
			mode:        f.lastMode,
		}
	case strings.Contains(query, "UPDATE workspace_sync_runs SET") && strings.Contains(query, "status        = 'failed'"):
		f.updateFailedCalls++
		if len(args) > 1 {
			f.lastErrorCode, _ = args[1].(*string)
		}
		if len(args) > 2 {
			f.lastErrorMessage, _ = args[2].(*string)
		}
		return syncRunRow{
			id:           f.runID,
			workspaceID:  f.workspaceID,
			status:       "failed",
			mode:         f.lastMode,
			errorCode:    f.lastErrorCode,
			errorMessage: f.lastErrorMessage,
		}
	case strings.Contains(query, "UPDATE workspace_sync_runs SET") && strings.Contains(query, "status      = 'success'"):
		f.updateSuccessCalls++
		return syncRunRow{
			id:          f.runID,
			workspaceID: f.workspaceID,
			status:      "success",
			mode:        f.lastMode,
		}
	default:
		f.t.Fatalf("unexpected query: %s", query)
		return errorRow{err: errors.New("unexpected query")}
	}
}

type workspaceRow struct {
	workspaceID pgtype.UUID
}

func (r workspaceRow) Scan(dest ...any) error {
	values := []any{
		r.workspaceID,
		"workspace",
		"Workspace",
		"management-repo",
		(*string)(nil),
		pgtype.Timestamptz{},
		pgtype.Timestamptz{},
	}
	return scanValues(dest, values)
}

type syncRunRow struct {
	id           pgtype.UUID
	workspaceID  pgtype.UUID
	status       string
	mode         string
	errorCode    *string
	errorMessage *string
}

func (r syncRunRow) Scan(dest ...any) error {
	changedPaths := json.RawMessage("[]")
	metadata := json.RawMessage("{}")
	values := []any{
		r.id,
		r.workspaceID,
		"redis_worker",
		(*string)(nil),
		pgtype.UUID{},
		pgtype.UUID{},
		r.mode,
		r.status,
		(*string)(nil),
		changedPaths,
		pgtype.Timestamptz{},
		pgtype.Timestamptz{},
		r.errorCode,
		r.errorMessage,
		metadata,
	}
	return scanValues(dest, values)
}

type errorRow struct {
	err error
}

func (r errorRow) Scan(...any) error {
	return r.err
}

func scanValues(dest []any, values []any) error {
	if len(dest) != len(values) {
		return errors.New("unexpected scan destination count")
	}
	for i, d := range dest {
		switch out := d.(type) {
		case *pgtype.UUID:
			v, ok := values[i].(pgtype.UUID)
			if !ok {
				return fmt.Errorf("scan[%d]: expected pgtype.UUID, got %T", i, values[i])
			}
			*out = v
		case *string:
			v, ok := values[i].(string)
			if !ok {
				return fmt.Errorf("scan[%d]: expected string, got %T", i, values[i])
			}
			*out = v
		case **string:
			v, ok := values[i].(*string)
			if !ok {
				return fmt.Errorf("scan[%d]: expected *string, got %T", i, values[i])
			}
			*out = v
		case *json.RawMessage:
			v, ok := values[i].(json.RawMessage)
			if !ok {
				return fmt.Errorf("scan[%d]: expected json.RawMessage, got %T", i, values[i])
			}
			*out = v
		case *pgtype.Timestamptz:
			v, ok := values[i].(pgtype.Timestamptz)
			if !ok {
				return fmt.Errorf("scan[%d]: expected pgtype.Timestamptz, got %T", i, values[i])
			}
			*out = v
		default:
			return errors.New("unsupported scan destination")
		}
	}
	return nil
}

func mustTestUUID(t *testing.T, raw string) pgtype.UUID {
	t.Helper()
	var uid pgtype.UUID
	if err := uid.Scan(raw); err != nil {
		t.Fatalf("scan uuid %s: %v", raw, err)
	}
	return uid
}

