94	func (h *handler) handleWorkspaceSync(ctx context.Context, t *asynq.Task) error {
95		var payload queue.WorkspaceSyncPayload
96		if err := json.Unmarshal(t.Payload(), &payload); err != nil {
97			return fmt.Errorf("unmarshal payload: %w", err)
98		}
99		if payload.RepoURL == "" {
100			return fmt.Errorf("repo_url is required: %w", asynq.SkipRetry)
101		}
102		if strings.TrimSpace(payload.WorkspaceID) == "" {
103			return fmt.Errorf("workspace_id is required for workspace sync: %w", asynq.SkipRetry)
104		}
105		if err := h.ensureWorkspaceExists(ctx, payload.WorkspaceID); err != nil {
106			return err
107		}
108		if payload.DefaultBranch == "" {
109			payload.DefaultBranch = "main"
110		}
111		ref := payload.Ref
112		if ref == "" {
113			ref = payload.DefaultBranch
114		}
115		trigger := payload.Trigger
116		if trigger == "" {
117			trigger = "redis_worker"
118		}
119		mode := payload.Mode
120		if mode == "" {
121			mode = "full"
122		}
123	
124		// Targeted sync: fetch and upsert a single feature only.
125		if mode == "targeted" && payload.FeatureID != "" {
126			return h.handleTargetedSync(ctx, payload, trigger, ref)
127		}
128	
129		// Full reconciliation: clear pending task-sync jobs first, then sync everything.
130		log.Printf("sync started workspace_id=%s repo_url=%s ref=%s", payload.WorkspaceID, payload.RepoURL, ref)
131	
132		// Delete all pending task-sync jobs before full reconciliation starts.
133		// The full read supersedes all queued partial updates.
134		inspector := h.openPendingTaskInspector()
135		defer func() {
136			if err := inspector.Close(); err != nil {
137				log.Printf("warn: close asynq inspector: %v", err)
138			}
139		}()
140		if _, err := clearPendingTaskSyncJobsForWorkspace(inspector, payload.WorkspaceID); err != nil {
141			err = fmt.Errorf("clear pending task-sync jobs for workspace %s: %w", payload.WorkspaceID, err)
142			h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
143			return err
144		}
145	
146		snap, err := h.github.ImportWorkspace(ctx, domain.ImportInput{
147			RepoURL:       payload.RepoURL,
148			DefaultBranch: ref,
149			Token:         h.token,
150		})
151		if err != nil {
152			h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
153			return err
154		}
155		if err := firstSnapshotSourceError(snap); err != nil {
156			h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
157			return err
158		}
159		snap.WorkspaceID = payload.WorkspaceID
160		snap.RepoURL = payload.RepoURL
161		if strings.TrimSpace(payload.Name) != "" {
162			snap.Name = payload.Name
163			snap.Slug = slugify(payload.Name)
164		}
165	
166		if err := h.db.SaveSnapshot(ctx, payload.WorkspaceID, snap); err != nil {
167			h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
168			return err
169		}
170		if err := h.upsertGitHubSource(ctx, payload.WorkspaceID, payload.RepoURL, payload.DefaultBranch); err != nil {
171			h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
172			return err
173		}
174		if err := h.recordSuccessfulRun(ctx, payload, trigger, mode, ref, snap.CommitSHA); err != nil {
175			return err
176		}
177	
178		log.Printf("sync finished workspace_id=%s commit_sha=%s", payload.WorkspaceID, snap.CommitSHA)
179		return nil
180	}
