189	func clearPendingTaskSyncJobsForWorkspace(inspector pendingTaskInspector, workspaceID string) (int, error) {
190		const pageSize = 100
191		deleted := 0
192		page := 1
193		for {
194			tasks, err := inspector.ListPendingTasks(queue.QueueTaskSync, asynq.Page(page), asynq.PageSize(pageSize))
195			if errors.Is(err, asynq.ErrQueueNotFound) {
196				return deleted, nil
197			}
198			if err != nil {
199				return deleted, fmt.Errorf("list pending task-sync jobs: %w", err)
200			}
201			if len(tasks) == 0 {
202				return deleted, nil
203			}
204	
205			deletedFromPage := false
206			for _, info := range tasks {
207				if info.Type != queue.TypeTaskSync {
208					continue
209				}
210				var payload queue.TaskSyncPayload
211				if err := json.Unmarshal(info.Payload, &payload); err != nil {
212					continue
213				}
214				if payload.WorkspaceID != workspaceID {
215					continue
216				}
217				if err := inspector.DeleteTask(queue.QueueTaskSync, info.ID); err != nil {
218					return deleted, fmt.Errorf("delete pending task-sync job %s: %w", info.ID, err)
219				}
220				deleted++
221				deletedFromPage = true
222			}
223	
224			if deletedFromPage {
225				page = 1
226				continue
227			}
228			if len(tasks) < pageSize {
229				return deleted, nil
230			}
231			page++
232		}
233	}
