266	// handleTaskSync processes task:sync jobs from the task-sync queue.
267	// It derives the source branch from workspace branch_pattern at drain time so
268	// duplicate webhook events always fetch the latest task branch HEAD.
269	func (h *handler) handleTaskSync(ctx context.Context, t *asynq.Task) error {
270		var payload queue.TaskSyncPayload
271		if err := json.Unmarshal(t.Payload(), &payload); err != nil {
272			return fmt.Errorf("unmarshal task sync payload: %w", err)
273		}
274		if payload.WorkspaceID == "" || payload.FeatureID == "" || payload.TaskID == "" {
275			return fmt.Errorf("task sync payload missing required fields: %+v", payload)
276		}
277	
278		log.Printf("task sync started workspace_id=%s feature_id=%s task_id=%s",
279			payload.WorkspaceID, payload.FeatureID, payload.TaskID)
280	
281		// Look up workspace to get repo_url and branch_pattern.
282		uid, err := pgUUID(payload.WorkspaceID)
283		if err != nil {
284			return err
285		}
286		ws, err := h.q.GetWorkspace(ctx, uid)
287		if err != nil {
288			return fmt.Errorf("get workspace for task sync: %w", err)
289		}
290		src, err := h.q.GetGitHubSource(ctx, uid)
291		if err != nil {
292			return fmt.Errorf("get github source for task sync: %w", err)
293		}
294	
295		// Derive the task branch from branch_pattern.
296		branchPattern := "feature/{feature_id}-{work_id}"
297		if ws.BranchPattern != nil && *ws.BranchPattern != "" {
298			branchPattern = *ws.BranchPattern
299		}
300		taskBranch := taskSyncBranch(payload, branchPattern)
301	
302		taskSnap, err := h.github.FetchTask(ctx, src.RepoURL, taskBranch, payload.FeatureID, payload.TaskID)
303		if err != nil {
304			h.recordTaskSyncFailed(ctx, payload, taskBranch, err)
305			return fmt.Errorf("fetch task %s/%s on branch %s: %w", payload.FeatureID, payload.TaskID, taskBranch, err)
306		}
307	
308		if err := h.db.SaveTaskSnapshot(ctx, payload.WorkspaceID, *taskSnap); err != nil {
309			h.recordTaskSyncFailed(ctx, payload, taskBranch, err)
310			return fmt.Errorf("save task snapshot %s/%s: %w", payload.FeatureID, payload.TaskID, err)
311		}
312		if err := h.recordTaskSyncSuccess(ctx, payload, taskBranch); err != nil {
313			return err
314		}
315	
316		log.Printf("task sync finished workspace_id=%s feature_id=%s task_id=%s",
317			payload.WorkspaceID, payload.FeatureID, payload.TaskID)
318		return nil
319	}
