325	// deriveBranch substitutes feature_id and task_id into a branch pattern.
326	// Pattern format: "feature/{feature_id}-{work_id}"
327	func deriveBranch(pattern, featureID, taskID string) string {
328		branch := pattern
329		branch = strings.ReplaceAll(branch, "{feature_id}", featureID)
330		branch = strings.ReplaceAll(branch, "{work_id}", taskID)
331		return branch
332	}
