554	func slugify(name string) string {
555		lower := strings.ToLower(name)
556		re := regexp.MustCompile(`[^a-z0-9]+`)
557		slug := re.ReplaceAllString(lower, "-")
558		return strings.Trim(slug, "-")
559	}
